[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <urn:example:step:reproject:1> ;
            sh:resultMessage "A processing step must produce at least one entity (prov:generated, or an entity that prov:wasGeneratedBy it)." ;
            sh:resultPath [ sh:alternativePath ( prov:generated [ sh:inversePath prov:wasGeneratedBy ] ) ] ;
            sh:resultSeverity sh:Violation ;
