[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode <run:source-2-score> ;
            sh:resultMessage "Hazard score must derive from model data with a mom:dataTime" ;
            sh:resultSeverity sh:Violation ;
            sh:sourceConstraint [ sh:message "Hazard score must derive from model data with a mom:dataTime" ;
                    sh:select """
            SELECT $this WHERE {
                $this <http://www.w3.org/ns/prov#type> <https://rss-hydro.lu/ns/mom/HazardScore> .
                FILTER NOT EXISTS {
                    $this <http://www.w3.org/ns/prov#wasDerivedFrom>+ ?data .
                    ?data <https://rss-hydro.lu/ns/mom/dataType> ?type ;
                          <https://rss-hydro.lu/ns/mom/dataTime> ?time .
                }
            }
        """ ] ;
            sh:sourceConstraintComponent sh:SPARQLConstraintComponent ;
            sh:sourceShape <https://rss-hydro.lu/ns/mom/rules/#hazardScoreDerivedFromDatedData> ;
            sh:value <run:source-2-score> ] .

